using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using FireSafety;
public static class SchoolFinalCapture {
static async Task<object> Sample(string label){var samples=new List<float>();double start=Time.realtimeSinceStartupAsDouble;int last=Time.frameCount;while(Time.realtimeSinceStartupAsDouble-start<10){await Task.Delay(8);if(Time.frameCount!=last){last=Time.frameCount;samples.Add(Time.unscaledDeltaTime*1000);}}samples.Sort();return new{label,samples=samples.Count,averageFps=1000/samples.Average(),medianMs=samples[samples.Count/2],p95Ms=samples[(int)((samples.Count-1)*.95)],drawCalls=UnityStats.drawCalls,triangles=UnityStats.triangles};}
public static async Task<string> Run(){Application.runInBackground=true;var s=TrainingSession.Instance;var p=s.player;var v=p.view;var local=v.localPosition;var rotation=v.localRotation;var data=new List<object>();s.MainMenu();s.ChooseMode(TrainingMode.FireExtinguisher);s.StartSimulation();data.Add(await Sample("Main classroom, fire and NPC evacuation"));await Task.Delay(6500);p.enabled=false;v.position=new Vector3(22,2.1f,-7);v.LookAt(new Vector3(8,1.2f,2));await Task.Delay(200);ScreenCapture.CaptureScreenshot("Assets/Screenshots/School-Final-Courtyard.png");data.Add(await Sample("Courtyard and assembled NPCs"));v.position=new Vector3(4.9f,1.65f,-11);v.LookAt(new Vector3(4.9f,1.65f,7));await Task.Delay(300);ScreenCapture.CaptureScreenshot("Assets/Screenshots/School-Final-Corridor.png");await Task.Delay(200);s.MainMenu();v.position=new Vector3(1.8f,1.6f,-1.2f);v.LookAt(new Vector3(-.6f,.95f,-2.8f));await Task.Delay(300);ScreenCapture.CaptureScreenshot("Assets/Screenshots/School-Final-Computers.png");await Task.Delay(200);v.localPosition=local;v.localRotation=rotation;p.enabled=true;s.MainMenu();var report=new{scope="Two 10-second Unity Editor Game view samples; not a standalone performance certification",gpu=SystemInfo.graphicsDeviceName,width=Screen.width,height=Screen.height,quality=QualitySettings.names[QualitySettings.GetQualityLevel()],samples=data};var json=Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented);File.WriteAllText(Path.GetFullPath("../Documentation/SchoolEditorPerformance.json"),json);return json;}}
